const MAX = 1024 * 1024; // 1 MB

function App() {
  const [file, setFile] = useState(null);
  const [error, setError] = useState("");
  const [preview, setPreview] = useState(null);

  function onChange(e) {
    const f = e.target.files && e.target.files[0];
    setError("");
    if (!f) { setFile(null); return; }
    if (!f.type.startsWith("image/")) { setError("Only images allowed"); setFile(null); return; }
    if (f.size > MAX) { setError("File larger than 1 MB"); setFile(null); return; }
    setFile(f);
  }

  useEffect(() => {
    if (!file) { setPreview(null); return; }
    const url = URL.createObjectURL(file);
    setPreview(url);
    return () => URL.revokeObjectURL(url);
  }, [file]);

  function upload() {
    const fd = new FormData();
    fd.append("avatar", file);
    console.log("would POST", file.name, fd.has("avatar"));
  }

  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      <input type="file" accept="image/*" onChange={onChange} />
      {error && <p style={{ color: "crimson" }}>{error}</p>}
      {file && (
        <div>
          <p>{file.name} - {(file.size / 1024).toFixed(1)} KB</p>
          {preview && <img src={preview} alt="preview" style={{ maxWidth: 160, maxHeight: 120 }} />}
          <div><button onClick={upload}>Upload</button></div>
        </div>
      )}
    </div>
  );
}

function App() {
  const [subscribed, setSubscribed] = useState(false);
  const [message, setMessage] = useState("");
  const emailId = useId();

  function toggle() {
    const next = !subscribed;
    setSubscribed(next);
    setMessage(next ? "You are subscribed." : "You are unsubscribed.");
  }

  return (
    <main style={{ fontFamily: "sans-serif", padding: 12 }}>
      <h2>Newsletter</h2>
      <label htmlFor={emailId}>Email address</label>
      <br />
      <input id={emailId} type="email" autoComplete="email" />
      <br />
      <button type="button" aria-pressed={subscribed} onClick={toggle} style={{ marginTop: 8 }}>
        {subscribed ? "Unsubscribe" : "Subscribe"}
      </button>
      <p role="status" aria-live="polite">{message}</p>
    </main>
  );
}
